import type { CourseBuilderData, Lesson, Module } from '../dashboard/CourseBuilder';

type UnknownRecord = Record<string, unknown>;

export interface CourseLessonLocation {
  lesson: Lesson;
  moduleId: string;
  moduleTitle: string;
  moduleIndex: number;
  lessonIndex: number;
}

const LESSON_TYPES = new Set<Lesson['type']>([
  'video',
  'text',
  'link',
  'audio',
  'pdf',
  'quiz',
]);

const asRecord = (value: unknown): UnknownRecord => (
  value && typeof value === 'object' && !Array.isArray(value)
    ? value as UnknownRecord
    : {}
);

const asString = (value: unknown) => typeof value === 'string' ? value : '';

const lessonType = (lesson: UnknownRecord): Lesson['type'] => {
  const rawType = asString(lesson.type).toLowerCase();
  const type = rawType as Lesson['type'];
  if (LESSON_TYPES.has(type)) return type;
  if (lesson.file_url || lesson.fileUrl || rawType === 'file' || rawType === 'document') return 'pdf';
  if (lesson.video_url || lesson.videoUrl) return 'video';
  return 'text';
};

const normalizeLesson = (value: unknown, moduleIndex: number, lessonIndex: number): Lesson => {
  const lesson = asRecord(value);
  const fallbackId = `module-${moduleIndex + 1}-lesson-${lessonIndex + 1}`;

  return {
    ...lesson,
    id: asString(lesson.id) || fallbackId,
    title: asString(lesson.title) || asString(lesson.name) || `Lesson ${lessonIndex + 1}`,
    type: lessonType(lesson),
    content: asString(lesson.content),
    videoUrl: asString(lesson.videoUrl) || asString(lesson.video_url) || undefined,
    duration: asString(lesson.duration) || undefined,
  } as Lesson;
};

const normalizeModule = (value: unknown, moduleIndex: number): Module => {
  const module = asRecord(value);
  const lessons = Array.isArray(module.lessons) ? module.lessons : [];

  return {
    ...module,
    id: asString(module.id) || `module-${moduleIndex + 1}`,
    title: asString(module.title) || asString(module.name) || `Module ${moduleIndex + 1}`,
    lessons: lessons.map((lesson, lessonIndex) => normalizeLesson(lesson, moduleIndex, lessonIndex)),
  } as Module;
};

export const getCourseModules = (metadata: unknown): Module[] => {
  const root = asRecord(metadata);
  const course = asRecord(root.course);
  const candidates = [course.modules, root.curriculum, root.modules];

  const source = candidates.find((candidate) => Array.isArray(candidate) && candidate.length > 0)
    ?? candidates.find(Array.isArray)
    ?? [];

  return (source as unknown[]).map(normalizeModule);
};

export const getCourseBuilderData = (metadata: unknown): Partial<CourseBuilderData> => {
  const root = asRecord(metadata);
  const course = asRecord(root.course);

  return {
    modules: getCourseModules(metadata),
    design: asRecord(course.design) as Partial<CourseBuilderData['design']> as CourseBuilderData['design'],
    settings: asRecord(course.settings) as Partial<CourseBuilderData['settings']> as CourseBuilderData['settings'],
  };
};

export const flattenCourseLessons = (modules: Module[]): CourseLessonLocation[] => (
  modules.flatMap((module, moduleIndex) => module.lessons.map((lesson, lessonIndex) => ({
    lesson,
    moduleId: module.id,
    moduleTitle: module.title,
    moduleIndex,
    lessonIndex,
  })))
);

export const isCourseListing = (listing: unknown): boolean => {
  const row = asRecord(listing);
  const metadata = asRecord(row.metadata);
  const type = asString(row.type).toLowerCase();
  const category = asString(row.category).toLowerCase();
  const digitalType = asString(metadata.digitalType).toLowerCase();
  const course = asRecord(metadata.course);

  return type === 'course'
    || category === 'course'
    || digitalType === 'course'
    || Array.isArray(course.modules)
    || Array.isArray(metadata.curriculum)
    || Array.isArray(metadata.modules);
};

export const getLessonMediaSource = (lesson: Lesson | null): string => {
  if (!lesson) return '';
  const row = lesson as Lesson & {
    video_url?: string;
    file_url?: string;
    fileUrl?: string;
    url?: string;
  };

  const explicitSource = row.videoUrl
    || row.video_url
    || row.file_url
    || row.fileUrl
    || row.url;
  if (explicitSource) return explicitSource;

  return lesson.type === 'audio' || lesson.type === 'pdf'
    ? lesson.content
    : '';
};
