import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import {
  AlertTriangle,
  Archive,
  Building2,
  ChevronLeft,
  Download,
  ExternalLink,
  FileText,
  Info,
  Loader2,
  Mail,
  MoreHorizontal,
  Send,
  ShieldBan,
  Sparkles,
  Tag,
  X,
} from 'lucide-react';
import { motion } from 'motion/react';
import { supabase } from '../../lib/supabase';
import type { PublicDmSubmission } from '../../types/publicDm';
import { appToast, destructiveAction } from '../../lib/feedback';
import { firstPublicIdentityLabel } from '../../lib/publicIdentity';

type ThreadMessage = {
  id: string;
  sender_type: 'guest' | 'owner';
  content: string;
  created_at: string;
};

type Props = {
  submission: PublicDmSubmission;
  userId?: string;
  onClose: () => void;
  onConversationRemoved?: (submissionId: string) => void;
};

const labelStyles: Record<PublicDmSubmission['label'], string> = {
  collaboration: 'border-violet-500/20 bg-violet-500/15 text-violet-300',
  support: 'border-sky-500/20 bg-sky-500/15 text-sky-300',
  question: 'border-amber-500/20 bg-amber-500/15 text-amber-200',
  spam: 'border-red-500/20 bg-red-500/15 text-red-300',
};

const labelNames: Record<PublicDmSubmission['label'], string> = {
  collaboration: 'Collaboration',
  support: 'Support',
  question: 'Question',
  spam: 'Spam',
};

const initials = (value: string) => value
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 2)
  .map((part) => part[0]?.toUpperCase())
  .join('') || 'DM';

export function PublicDmConversation({
  submission,
  userId,
  onClose,
  onConversationRemoved,
}: Props) {
  const [messages, setMessages] = useState<ThreadMessage[]>([]);
  const [reply, setReply] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [actionsOpen, setActionsOpen] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const displayName = firstPublicIdentityLabel([submission.guest_name, submission.guest_email], 'Public DM guest');

  useEffect(() => {
    if (!userId) return;
    let active = true;
    setLoading(true);
    setMessages([]);
    void supabase
      .from('public_dm_messages')
      .select('id, sender_type, content, created_at')
      .eq('submission_id', submission.id)
      .eq('owner_id', userId)
      .order('created_at', { ascending: true })
      .then(({ data, error }) => {
        if (!active) return;
        if (error) {
          appToast('This conversation could not be loaded.');
        } else {
          setMessages((data || []) as ThreadMessage[]);
        }
        setLoading(false);
      });

    const channel = supabase
      .channel(`public-dm-conversation:${submission.id}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'public_dm_messages',
        filter: `submission_id=eq.${submission.id}`,
      }, (payload) => {
        const message = payload.new as ThreadMessage;
        setMessages((current) => current.some((item) => item.id === message.id)
          ? current
          : [...current, message]);
      })
      .subscribe();

    return () => {
      active = false;
      void supabase.removeChannel(channel);
    };
  }, [submission.id, userId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages.length, loading]);

  const sendReply = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const content = reply.trim();
    if (!content || !userId || sending) return;
    setSending(true);
    const { data, error } = await supabase
      .from('public_dm_messages')
      .insert({
        submission_id: submission.id,
        owner_id: userId,
        sender_type: 'owner',
        sender_user_id: userId,
        content,
      })
      .select('id, sender_type, content, created_at')
      .single();
    setSending(false);
    if (error || !data) {
      appToast(error?.message || 'Your reply could not be sent.');
      return;
    }
    setReply('');
    setMessages((current) => current.some((item) => item.id === data.id)
      ? current
      : [...current, data as ThreadMessage]);
  };

  const updateStatus = async (status: PublicDmSubmission['status']) => {
    if (!userId) return;
    const { error } = await supabase
      .from('public_dm_submissions')
      .update({
        status,
        archived_at: status === 'archived' ? new Date().toISOString() : null,
      })
      .eq('id', submission.id)
      .eq('owner_id', userId);
    if (error) {
      appToast('This conversation could not be updated.');
      return;
    }
    onConversationRemoved?.(submission.id);
    appToast(status === 'spam' ? 'Conversation moved to spam.' : 'Conversation archived.');
  };

  const blockSender = async () => {
    if (!userId) return;
    if (!await destructiveAction({ description: 'Block this sender from sending future public DMs?' })) return;
    const blockedEmailHash = submission.guest_email_hash || '';
    if (!submission.sender_user_id && !blockedEmailHash) {
      appToast('This guest has no account or email address that can be blocked.');
      return;
    }
    const { error } = submission.sender_user_id
      ? await supabase.from('public_dm_blocks').upsert({
        owner_id: userId,
        blocked_user_id: submission.sender_user_id,
        reason: 'Blocked from public DM inbox',
      })
      : await supabase.from('public_dm_blocks').upsert({
        owner_id: userId,
        blocked_email_hash: blockedEmailHash,
        reason: 'Blocked from public DM inbox',
      });
    if (error) {
      appToast('The sender could not be blocked.');
      return;
    }
    await updateStatus('spam');
  };

  const downloadAttachment = async (path: string) => {
    const { data, error } = await supabase.storage
      .from('public-dm-attachments')
      .createSignedUrl(path, 60);
    if (error || !data?.signedUrl) {
      appToast('The attachment could not be opened securely.');
      return;
    }
    window.open(data.signedUrl, '_blank', 'noopener,noreferrer');
  };

  return (
    <motion.div
      key={submission.id}
      initial={{ opacity: 0, x: 12 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -12 }}
      transition={{ duration: 0.18 }}
      className="flex h-full min-h-0 w-full flex-1 overflow-hidden"
    >
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="chat-conversation-header z-10 flex min-h-[68px] shrink-0 items-center justify-between gap-2 border-b px-2.5 pt-[env(safe-area-inset-top)] backdrop-blur-2xl md:h-20 md:px-6 md:pt-0">
          <div className="flex min-w-0 items-center gap-2.5 md:gap-3">
            <button
              type="button"
              onClick={onClose}
              className="chat-icon-button flex h-10 w-10 shrink-0 items-center justify-center rounded-full transition-transform active:scale-90 md:hidden"
              aria-label="Back to chats"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-indigo-500 to-blue-500 text-xs font-black text-white shadow-lg shadow-indigo-500/15 md:h-12 md:w-12">
              {initials(displayName)}
            </span>
            <span className="min-w-0">
              <span className="chat-primary-text block truncate text-[14px] font-bold md:text-base">{displayName}</span>
              <span className="mt-0.5 flex items-center gap-1.5 text-[10px] font-semibold text-emerald-400/80 md:text-[11px]">
                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
                Public DM conversation
              </span>
            </span>
          </div>
          <div className="relative flex shrink-0 items-center gap-1.5">
            <button
              type="button"
              onClick={() => setDetailsOpen((current) => !current)}
              className={`chat-icon-button flex h-10 w-10 items-center justify-center rounded-full ${detailsOpen ? 'text-blue-400' : ''}`}
              aria-label="Conversation details"
              aria-pressed={detailsOpen}
            >
              <Info className="h-[18px] w-[18px]" />
            </button>
            <button
              type="button"
              onClick={() => setActionsOpen((current) => !current)}
              className="chat-icon-button flex h-10 w-10 items-center justify-center rounded-full"
              aria-label="Conversation actions"
              aria-expanded={actionsOpen}
            >
              <MoreHorizontal className="h-[19px] w-[19px]" />
            </button>
            {actionsOpen && (
              <div className="absolute right-0 top-12 z-40 w-52 overflow-hidden rounded-2xl border border-white/10 bg-[#181818] p-1.5 shadow-2xl">
                <button type="button" onClick={() => void updateStatus('archived')} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-gray-200 hover:bg-white/[0.06]">
                  <Archive className="h-4 w-4" /> Archive conversation
                </button>
                <button type="button" onClick={() => void updateStatus('spam')} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-amber-200 hover:bg-white/[0.06]">
                  <AlertTriangle className="h-4 w-4" /> Move to spam
                </button>
                <button type="button" onClick={() => void blockSender()} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-red-300 hover:bg-white/[0.06]">
                  <ShieldBan className="h-4 w-4" /> Block sender
                </button>
              </div>
            )}
          </div>
        </header>

        <div className="chat-message-list flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-3 py-5 pb-6 scrollbar-hide md:gap-6 md:p-8">
          <div className="mx-auto flex max-w-sm flex-col items-center py-2 text-center">
            <span className="mb-3 flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-500/10 text-indigo-300">
              <Mail className="h-6 w-6" />
            </span>
            <h2 className="chat-primary-text text-base font-bold">{submission.subject || 'Public DM'}</h2>
            <p className="chat-secondary-text mt-1 text-xs">
              Started {new Date(submission.created_at).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' })}
            </p>
          </div>

          <div className="flex items-end gap-2 md:gap-3">
            <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-white/10 text-[9px] font-bold text-gray-300 md:h-9 md:w-9">
              {initials(displayName)}
            </span>
            <div className="chat-message-bubble is-theirs max-w-[78vw] rounded-[20px] rounded-bl-[6px] border p-3 shadow-sm md:max-w-md md:p-4">
              <div className="mb-1 text-[11px] font-bold text-indigo-400">{displayName}</div>
              <p className="whitespace-pre-wrap text-[14px] leading-6">{submission.message}</p>
              <span className="mt-1 block text-right text-[10px] text-gray-500">
                {new Date(submission.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>

          {loading ? (
            <div className="flex justify-center py-6"><Loader2 className="h-5 w-5 animate-spin text-gray-600" /></div>
          ) : messages.map((message) => {
            const fromOwner = message.sender_type === 'owner';
            return (
              <motion.div
                key={message.id}
                initial={{ opacity: 0, y: 10, scale: 0.98 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                className={`flex items-end gap-2 md:gap-3 ${fromOwner ? 'flex-row-reverse' : ''}`}
              >
                <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-bold md:h-9 md:w-9 ${
                  fromOwner ? 'bg-indigo-500 text-white' : 'bg-white/10 text-gray-300'
                }`}>
                  {fromOwner ? 'You' : initials(displayName)}
                </span>
                <div className={`chat-message-bubble max-w-[78vw] rounded-[20px] p-3 shadow-sm md:max-w-md md:p-4 ${
                  fromOwner
                    ? 'is-mine rounded-br-[6px] text-white'
                    : 'is-theirs rounded-bl-[6px] border'
                }`}>
                  {!fromOwner && <div className="mb-1 text-[11px] font-bold text-indigo-400">{displayName}</div>}
                  <p className="whitespace-pre-wrap text-[14px] leading-6">{message.content}</p>
                  <span className={`mt-1 block text-right text-[10px] ${fromOwner ? 'text-white/60' : 'text-gray-500'}`}>
                    {new Date(message.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </motion.div>
            );
          })}
          <div ref={messagesEndRef} />
        </div>

        <form onSubmit={sendReply} className="chat-composer-shell shrink-0 border-t px-3 pb-[max(12px,env(safe-area-inset-bottom))] pt-3 md:px-6 md:pb-5">
          <div className="flex items-end gap-2 rounded-[22px] border border-white/[0.08] bg-white/[0.045] p-2 pl-4">
            <textarea
              rows={1}
              value={reply}
              onChange={(event) => setReply(event.target.value.slice(0, 3000))}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault();
                  event.currentTarget.form?.requestSubmit();
                }
              }}
              placeholder={`Message ${displayName}`}
              className="max-h-32 min-h-10 min-w-0 flex-1 resize-none bg-transparent py-2 text-sm text-white outline-none placeholder:text-gray-600"
            />
            <button
              type="submit"
              disabled={!reply.trim() || sending}
              className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-blue-500 text-white shadow-lg shadow-blue-500/20 transition-transform active:scale-90 disabled:opacity-35"
              aria-label="Send reply"
            >
              {sending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
            </button>
          </div>
          <p className="chat-tertiary-text mt-2 hidden text-center text-[10px] md:block">
            Replies are delivered securely to this public DM conversation.
          </p>
        </form>
      </div>

      {detailsOpen && (
        <aside className="absolute inset-0 z-30 flex min-w-0 flex-col overflow-y-auto border-l border-white/[0.07] bg-[#111]/95 p-5 backdrop-blur-2xl md:relative md:inset-auto md:w-[320px] md:shrink-0 md:bg-white/[0.018]">
          <div className="mb-6 flex items-center justify-between">
            <h3 className="chat-primary-text text-sm font-bold">Conversation details</h3>
            <button type="button" onClick={() => setDetailsOpen(false)} className="chat-icon-button flex h-9 w-9 items-center justify-center rounded-full" aria-label="Close details">
              <X className="h-4 w-4" />
            </button>
          </div>

          <div className="mb-5 flex flex-col items-center text-center">
            <span className="mb-3 flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-indigo-500 to-blue-500 text-sm font-black text-white">
              {initials(displayName)}
            </span>
            <p className="chat-primary-text font-bold">{displayName}</p>
            <p className="chat-tertiary-text mt-1 text-xs">{submission.guest_email || 'No email provided'}</p>
          </div>

          <div className="mb-4 flex flex-wrap justify-center gap-2 text-[10px]">
            <span className={`rounded-full border px-2.5 py-1 font-semibold ${labelStyles[submission.label]}`}>
              <Tag className="mr-1 inline h-3 w-3" /> {labelNames[submission.label]}
            </span>
            {submission.ai_classification_status === 'ai_verified' && (
              <span className="rounded-full bg-violet-500/10 px-2.5 py-1 font-semibold text-violet-200">
                <Sparkles className="mr-1 inline h-3 w-3" /> AI checked
              </span>
            )}
          </div>

          <div className="space-y-3 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4 text-xs">
            {submission.company_name && (
              <p className="chat-secondary-text flex gap-2"><Building2 className="h-4 w-4 shrink-0" />{submission.company_name}</p>
            )}
            {submission.website_url && (
              <a className="flex gap-2 text-indigo-300 hover:underline" href={submission.website_url} target="_blank" rel="noreferrer">
                <ExternalLink className="h-4 w-4 shrink-0" />Website or social profile
              </a>
            )}
            <p className="chat-secondary-text">{submission.primary_category || labelNames[submission.label]} · {submission.subcategory || 'General'}</p>
            {submission.country_code && <p className="chat-tertiary-text">Country: {submission.country_code}</p>}
          </div>

          {Object.keys(submission.custom_answers || {}).length > 0 && (
            <div className="mt-5 space-y-2">
              <h4 className="chat-primary-text text-xs font-bold">Custom answers</h4>
              {Object.entries(submission.custom_answers).map(([question, answer]) => (
                <div key={question} className="rounded-xl border border-white/[0.07] p-3">
                  <p className="chat-tertiary-text text-[10px]">{question}</p>
                  <p className="chat-secondary-text mt-1 text-xs">{answer}</p>
                </div>
              ))}
            </div>
          )}

          {submission.attachments?.length > 0 && (
            <div className="mt-5 space-y-2">
              <h4 className="chat-primary-text text-xs font-bold">Attachments</h4>
              {submission.attachments.map((attachment) => (
                <button
                  type="button"
                  key={attachment.path}
                  onClick={() => void downloadAttachment(attachment.path)}
                  className="flex w-full items-center gap-3 rounded-xl border border-white/[0.07] p-3 text-left hover:bg-white/5"
                >
                  <FileText className="h-4 w-4 text-indigo-300" />
                  <span className="chat-secondary-text min-w-0 flex-1 truncate text-xs">{attachment.name}</span>
                  <Download className="h-3.5 w-3.5 text-gray-500" />
                </button>
              ))}
            </div>
          )}

          <div className="mt-auto grid gap-2 pt-6">
            <button type="button" onClick={() => void updateStatus('archived')} className="flex items-center justify-center gap-2 rounded-xl bg-white/[0.07] px-4 py-2.5 text-xs font-semibold text-white hover:bg-white/10">
              <Archive className="h-4 w-4" /> Archive
            </button>
            <button type="button" onClick={() => void blockSender()} className="flex items-center justify-center gap-2 rounded-xl bg-red-500/10 px-4 py-2.5 text-xs font-semibold text-red-300 hover:bg-red-500/15">
              <ShieldBan className="h-4 w-4" /> Block sender
            </button>
          </div>
        </aside>
      )}
    </motion.div>
  );
}
