interface WorkspaceAiSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  context?: AiPageContext;
  onNavigate?: (view: string) => void;
}

interface UiMessage extends Partial<AiMessage> {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  created_at: string;
}

const formatValue = (value: unknown) => {
  if (value === null || value === undefined || value === '') return 'Empty';
  if (typeof value === 'object') return JSON.stringify(value, null, 2);
  return String(value);
};

const ResultChart: React.FC<{ result: AiActionResult }> = ({ result }) => {
  const chart = result.chart;
  if (!chart?.data?.length) return null;
  const colors = ['#8b5cf6', '#22d3ee', '#34d399', '#fbbf24', '#fb7185'];
  return (
    <div className="mt-3 h-52 rounded-2xl border border-white/10 bg-black/25 p-3">
      <p className="mb-2 text-xs font-semibold text-white">{chart.title}</p>
      <ResponsiveContainer width="100%" height="88%">
        {chart.type === 'pie' ? (
          <PieChart>
            <Pie data={chart.data} dataKey={chart.yKey} nameKey={chart.xKey} innerRadius={35} outerRadius={65}>
              {chart.data.map((_, index) => <Cell key={index} fill={colors[index % colors.length]} />)}
            </Pie>
            <Tooltip />
          </PieChart>
        ) : chart.type === 'bar' ? (
          <BarChart data={chart.data}>
            <CartesianGrid stroke="#27272a" strokeDasharray="3 3" vertical={false} />
            <XAxis dataKey={chart.xKey} stroke="#71717a" fontSize={10} />
            <YAxis stroke="#71717a" fontSize={10} />
            <Tooltip contentStyle={{ background: '#09090b', borderColor: '#27272a', borderRadius: 12 }} />
            <Bar dataKey={chart.yKey} fill="#8b5cf6" radius={[6, 6, 0, 0]} />
          </BarChart>
        ) : (
          <LineChart data={chart.data}>
            <CartesianGrid stroke="#27272a" strokeDasharray="3 3" vertical={false} />
            <XAxis dataKey={chart.xKey} stroke="#71717a" fontSize={10} />
            <YAxis stroke="#71717a" fontSize={10} />
            <Tooltip contentStyle={{ background: '#09090b', borderColor: '#27272a', borderRadius: 12 }} />
            <Line type="monotone" dataKey={chart.yKey} stroke="#8b5cf6" strokeWidth={2} dot={false} />
          </LineChart>
        )}
      </ResponsiveContainer>
    </div>
  );
};

const ActionCard: React.FC<{
  action: AiAction;
  busy: boolean;
  onApprove: () => void;
  onReject: () => void;
  onUndo: () => void;
  onOpen: (route: string) => void;
}> = ({ action, busy, onApprove, onReject, onUndo, onOpen }) => {
  const preview = action.preview;
  const waiting = action.status === 'waiting_for_approval' || action.status === 'proposed';
  const completed = action.status === 'completed';
  const failed = action.status === 'failed' || action.status === 'rejected';
  return (
    <div className={`mt-3 overflow-hidden rounded-2xl border ${waiting ? 'border-amber-400/35 bg-amber-400/[0.06]' : completed ? 'border-emerald-400/25 bg-emerald-400/[0.05]' : 'border-white/10 bg-white/[0.03]'}`}>
      <div className="flex items-start gap-3 p-3.5">
        <div className={`mt-0.5 rounded-xl p-2 ${waiting ? 'bg-amber-400/15 text-amber-300' : completed ? 'bg-emerald-400/15 text-emerald-300' : 'bg-white/10 text-zinc-300'}`}>
          {waiting ? <ShieldAlert className="h-4 w-4" /> : completed ? <Check className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center justify-between gap-2">
            <p className="truncate text-sm font-semibold text-white">{action.title || preview?.title || action.toolName}</p>
            <span className="rounded-full border border-white/10 px-2 py-0.5 text-[10px] uppercase tracking-wide text-zinc-400">{action.riskLevel}</span>
          </div>
          <p className="mt-1 text-xs leading-5 text-zinc-400">{preview?.summary || action.result?.summary || (failed ? 'This action was not applied.' : 'Review the proposed action.')}</p>
        </div>
      </div>

      {preview?.changes?.length ? (
        <div className="border-t border-white/8 px-3.5 py-3">
          <p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.16em] text-zinc-500">Proposed changes</p>
          <div className="space-y-2">
            {preview.changes.slice(0, 8).map((change, index) => (
              <div key={`${change.field}-${index}`} className="grid grid-cols-[90px_1fr] gap-2 text-xs">
                <span className="text-zinc-500">{change.field}</span>
                <div className="min-w-0 text-zinc-300">
                  <span className="line-through opacity-50">{formatValue(change.before)}</span>
                  <span className="mx-1.5 text-zinc-600">→</span>
                  <span>{formatValue(change.after)}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : null}

      {preview?.financial ? (
        <div className="border-t border-white/8 px-3.5 py-2.5 text-xs text-zinc-300">
          Financial value: <strong className="text-white">{new Intl.NumberFormat(undefined, { style: 'currency', currency: preview.financial.currency }).format(preview.financial.amount)}</strong>
        </div>
      ) : null}

      {action.result ? <div className="border-t border-white/8 px-3.5 pb-3"><ResultChart result={action.result} /></div> : null}

      <div className="flex items-center gap-2 border-t border-white/8 p-3">
        {waiting ? (
          <>
            <button disabled={busy} onClick={onApprove} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-white px-3 py-2 text-xs font-semibold text-black transition hover:bg-zinc-200 disabled:opacity-50">
              {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />} Approve
            </button>
            <button disabled={busy} onClick={onReject} className="rounded-xl border border-white/10 px-3 py-2 text-xs font-medium text-zinc-300 hover:bg-white/5 disabled:opacity-50">Reject</button>
          </>
        ) : completed ? (
          <>
            {action.reversible === true && <button disabled={busy} onClick={onUndo} className="flex items-center gap-2 rounded-xl border border-white/10 px-3 py-2 text-xs font-medium text-zinc-300 hover:bg-white/5 disabled:opacity-50"><Undo2 className="h-3.5 w-3.5" /> Undo</button>}
            {action.result?.resource?.route && <button onClick={() => onOpen(action.result!.resource!.route!)} className="ml-auto flex items-center gap-1.5 rounded-xl px-3 py-2 text-xs font-semibold text-violet-300 hover:bg-violet-400/10">Open <ArrowRight className="h-3.5 w-3.5" /></button>}
          </>
        ) : <span className="text-xs text-zinc-500">No changes were applied.</span>}
      </div>
    </div>
  );
};

export const WorkspaceAiSidebar: React.FC<WorkspaceAiSidebarProps> = ({
  isOpen,
  onClose,
  context: propContext = {},
  onNavigate,
}) => {
  const { context: registeredContext } = useWerseeAiContext();
  const context = useMemo(() => ({ ...registeredContext, ...propContext }), [registeredContext, propContext]);
  const businessId = typeof context.businessId === 'string' ? context.businessId : undefined;
  const isPrivateChatMode = context.page === 'chats' && context.chatPrivacyMode === true;
  const [dismissedChatIntro, setDismissedChatIntro] = useState(false);
  const [conversations, setConversations] = useState<AiConversation[]>([]);
  const [conversationId, setConversationId] = useState<string>();
  const [messages, setMessages] = useState<UiMessage[]>([]);
  const [actions, setActions] = useState<Record<string, AiAction>>({});
  const [prompt, setPrompt] = useState('');
  const [lastPrompt, setLastPrompt] = useState('');
  const [isRunning, setIsRunning] = useState(false);
  const [runId, setRunId] = useState<string>();
  const [stepLabel, setStepLabel] = useState('');
  const [activeToolName, setActiveToolName] = useState<string>();
  const [mobileResponseId, setMobileResponseId] = useState<string>();
  const [error, setError] = useState<WerseeAiError | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [showActivity, setShowActivity] = useState(false);
  const [activity, setActivity] = useState<any[]>([]);
  const [actionBusy, setActionBusy] = useState<string>();
  const abortRef = useRef<AbortController | undefined>(undefined);
  const endRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    setDismissedChatIntro(false);
  }, [context.entityId]);

  useEffect(() => {
    if (!isOpen || !isPrivateChatMode) return;
    setConversationId(undefined);
    setMessages([]);
    setActions({});
    setMobileResponseId(undefined);
    setError(null);
    setShowHistory(false);
    setShowActivity(false);
  }, [context.entityId, isOpen, isPrivateChatMode]);

  const refreshConversations = useCallback(async () => {
    const data = await werseeAi.listConversations(businessId);
    setConversations(data.conversations as AiConversation[]);
  }, [businessId]);

  const openActivity = async () => {
    setShowActivity(true);
    try {
      const data = await werseeAi.getActivity(businessId);
      setActivity(data.activity || []);
    } catch (reason) {
      setError(reason as WerseeAiError);
    }
  };

  useEffect(() => {
    if (!isOpen) return;
    refreshConversations().catch((reason) => setError(reason as WerseeAiError));
    window.setTimeout(() => textareaRef.current?.focus(), 180);
  }, [isOpen, refreshConversations]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, actions, isRunning]);

  const loadConversation = async (id: string) => {
    setError(null);
    try {
      const data = await werseeAi.getConversation(id);
      setConversationId(id);
      setMobileResponseId(undefined);
      setMessages((data.messages || []).map((message: AiMessage) => ({
        ...message,
        id: message.id,
        role: message.role === 'user' ? 'user' : 'assistant',
        content: message.content || '',
        created_at: message.created_at,
      })));
      setActions(Object.fromEntries((data.actions || []).map((item: any) => [item.id, {
        id: item.id,
        toolName: item.tool_name,
        category: item.category,
        riskLevel: item.risk_level,
        status: item.status,
        preview: item.preview,
        result: item.sanitized_result,
        reversible: item.reversible,
      }])));
      setShowHistory(false);
    } catch (reason) {
      setError(asWerseeAiError(reason, 'The conversation could not be loaded.'));
    }
  };

  const newConversation = () => {
    setConversationId(undefined);
    setMessages([]);
    setActions({});
    setMobileResponseId(undefined);
    setError(null);
    setShowHistory(false);
    window.setTimeout(() => textareaRef.current?.focus(), 50);
  };

  const deleteConversation = async (id: string) => {
    if (!window.confirm('Delete this Wersee AI conversation and its stored messages?')) return;
    try {
      await werseeAi.archiveConversation(id);
      if (conversationId === id) newConversation();
      setConversations((current) => current.filter((conversation) => conversation.id !== id));
    } catch (reason) {
      setError(asWerseeAiError(reason, 'The conversation could not be deleted.'));
    }
  };

  const sendPrompt = async (override?: string) => {
    const value = (override ?? prompt).trim();
    if (!value || isRunning) return;
    const controller = new AbortController();
    abortRef.current = controller;
    setPrompt('');
    setLastPrompt(value);
    setError(null);
    setIsRunning(true);
    setStepLabel('Understanding your request');
    setActiveToolName(undefined);
    const optimisticId = crypto.randomUUID();
    const assistantId = crypto.randomUUID();
    setMobileResponseId(assistantId);
    setMessages((current) => [...current, { id: optimisticId, role: 'user', content: value, created_at: new Date().toISOString() }, { id: assistantId, role: 'assistant', content: '', created_at: new Date().toISOString() }]);
    try {
      if (isPrivateChatMode) {
        const privateContext = {
          chatName: typeof context.chatName === 'string' ? context.chatName : 'Private chat',
          draft: typeof context.chatDraft === 'string' ? context.chatDraft : '',
          recentMessages: Array.isArray(context.chatExcerpt) ? context.chatExcerpt : [],
        };
        const { text } = await werseeAi.generateText({
          contents: `REQUEST: ${value}\n\nPRIVATE_CHAT_CONTEXT:\n${JSON.stringify(privateContext)}`,
          config: {
            temperature: 0.25,
            maxOutputTokens: 900,
            systemInstruction: 'You are Wersee AI inside an opt-in private chat. Use only the supplied excerpt and draft. Never claim you sent or changed a message. Do not invent people, deadlines, decisions, or facts. Return the result directly and concisely.',
          },
        }, controller.signal);
        setMessages((current) => current.map((item) =>
          item.id === assistantId ? { ...item, content: text.trim() } : item,
        ));
        return;
      }
      for await (const event of werseeAi.chat({
        conversationId,
        message: value,
        mode: 'assistant',
        context,
        signal: controller.signal,
      })) {
        if (event.type === 'run.started') {
          setRunId(event.runId);
          setConversationId(event.conversationId);
        } else if (event.type === 'step.started') {
          setStepLabel(event.label);
        } else if (event.type === 'message.delta') {
          setMessages((current) => current.map((item) => item.id === assistantId ? { ...item, content: item.content + event.text } : item));
        } else if (event.type === 'action.proposed') {
          setActiveToolName(event.action.toolName);
          setStepLabel(humanizeAiTool(event.action.toolName));
          setActions((current) => ({ ...current, [event.action.id]: event.action }));
        } else if (event.type === 'action.started') {
          setActiveToolName(event.toolName);
          setStepLabel(event.label || humanizeAiTool(event.toolName));
          setActions((current) => ({ ...current, [event.actionId]: { ...(current[event.actionId] || { id: event.actionId, toolName: event.toolName || 'Wersee action', category: event.category, riskLevel: 'read' }), status: 'running' } }));
        } else if (event.type === 'action.completed') {
          setActions((current) => ({ ...current, [event.actionId]: { ...(current[event.actionId] || { id: event.actionId, toolName: 'Wersee action', riskLevel: 'low' }), status: 'completed', result: event.result, reversible: event.reversible } }));
        } else if (event.type === 'action.failed') {
          setActions((current) => current[event.actionId] ? ({ ...current, [event.actionId]: { ...current[event.actionId], status: 'failed' } }) : current);
        } else if (event.type === 'run.failed') {
          throw new WerseeAiError(event.error.message, event.error.code, event.error.retryable);
        }
      }
      setMessages((current) => current.filter((item) => item.id !== assistantId || item.content.trim()));
      await refreshConversations();
    } catch (reason) {
      if (!controller.signal.aborted) setError(reason instanceof WerseeAiError ? reason : new WerseeAiError('Wersee AI could not complete the request.', 'AI_REQUEST_FAILED', true));
      setMessages((current) => current.filter((item) => item.id !== assistantId || item.content.trim()));
    } finally {
      setIsRunning(false);
      setStepLabel('');
      setActiveToolName(undefined);
      abortRef.current = undefined;
    }
  };

  const stopRun = async () => {
    abortRef.current?.abort();
    if (runId) await werseeAi.cancelRun(runId).catch(() => null);
    setIsRunning(false);
    setStepLabel('');
    setActiveToolName(undefined);
  };

  const mutateAction = async (id: string, operation: 'approve' | 'reject' | 'undo') => {
    setActionBusy(id);
    setError(null);
    try {
      if (operation === 'reject') {
        await werseeAi.rejectAction(id);
        setActions((current) => ({ ...current, [id]: { ...current[id], status: 'rejected' } }));
      } else {
        const response = operation === 'approve' ? await werseeAi.approveAction(id) : await werseeAi.undoAction(id);
        setActions((current) => ({
          ...current,
          [id]: {
            ...current[id],
            status: operation === 'undo' ? 'undone' : 'completed',
            result: response.result,
            reversible: operation === 'undo' ? false : ('reversible' in response && response.reversible),
          },
        }));
      }
    } catch (reason) {
      setError(reason instanceof WerseeAiError ? reason : new WerseeAiError('The action could not be completed.'));
    } finally {
      setActionBusy(undefined);
    }
  };

  const orderedActions = Object.values(actions);
  const visibleActions = orderedActions.filter((action) => action.status !== 'running');
  const mobileAssistantMessage = mobileResponseId
    ? messages.find((message) => message.id === mobileResponseId && message.role === 'assistant')
    : undefined;
  const latestActionResult = [...orderedActions].reverse().find((action) => action.result?.summary)?.result?.summary;
  const mobileResult = mobileAssistantMessage?.content.trim() || latestActionResult;
  const contextLabel = isPrivateChatMode
    ? `Private chat · ${String(context.chatName || 'current chat')}`
    : String(context.businessName || context.page || context.activeView || 'Current workspace');
  const activityLabel = isRunning
    ? (stepLabel || humanizeAiTool(activeToolName))
    : mobileResult
      ? 'Result ready — continue when you are ready'
      : `Ready in ${contextLabel}`;
  const composerMenuItems: CodexComposerMenuItem[] = [
    ...(isPrivateChatMode ? CHAT_AI_ACTIONS.slice(0, 4).map((action) => ({
      label: action.label,
      description: 'Use the visible chat context only',
      icon: codexComposerIcons.Sparkles,
      onSelect: () => void sendPrompt(action.prompt),
    })) : [{
      label: 'New conversation',
      description: 'Start with a clean thread',
      icon: codexComposerIcons.MessageSquarePlus,
      onSelect: newConversation,
    }, {
      label: 'Conversation history',
      description: 'Open your saved AI threads',
      icon: codexComposerIcons.History,
      onSelect: () => setShowHistory(true),
    }, {
      label: 'Activity log',
      description: 'Review completed AI actions',
      icon: Activity,
      onSelect: () => void openActivity(),
    }]),
  ];

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.button
            aria-label="Close Wersee AI"
            className="fixed inset-0 z-[119] cursor-default bg-black/30 backdrop-blur-[2px] md:bg-black/20"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.aside
            aria-label="Wersee AI"
            className="fixed inset-0 z-[120] flex h-[100dvh] flex-col overflow-hidden bg-transparent text-white md:inset-y-0 md:left-auto md:right-0 md:h-auto md:w-[460px] md:border-l md:border-white/[0.09] md:bg-[#09090b]/[0.985] md:shadow-[-28px_0_80px_rgba(0,0,0,0.52)]"
            initial={{ x: '100%', opacity: 0.6 }} animate={{ x: 0, opacity: 1 }} exit={{ x: '100%', opacity: 0.5 }}
            transition={{ type: 'spring', damping: 30, stiffness: 285 }}
          >
            <header className="shrink-0 border-b border-white/[0.07] bg-black/30 px-4 pb-4 pt-[max(12px,env(safe-area-inset-top))] backdrop-blur-2xl md:bg-transparent md:px-5 md:pt-4">
              <div className="flex items-center gap-3">
                <button onClick={onClose} className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/[0.09] bg-black/35 text-white/70 transition hover:bg-white/10 hover:text-white md:hidden" aria-label="Back to workspace"><ArrowLeft className="h-4.5 w-4.5" /></button>
                <div className="min-w-0 flex-1">
                  <h2 className="text-sm font-semibold tracking-tight">Wersee AI</h2>
                  <p className="mt-0.5 truncate text-[11px] text-white/38">{contextLabel}</p>
                </div>
                <button onClick={onClose} className="hidden rounded-full p-2.5 text-white/42 transition hover:bg-white/[0.06] hover:text-white md:grid" aria-label="Close Wersee AI"><PanelRightClose className="h-4.5 w-4.5" /></button>
              </div>
              <CodexActivityPills active={isRunning} toolName={activeToolName} label={activityLabel} className="mt-4 hidden md:flex" />
              {isPrivateChatMode && (
                <div className="mt-3 flex items-center gap-2 px-1 text-[10px] font-medium text-emerald-100/55">
                  <ShieldCheck className="h-3.5 w-3.5 text-emerald-300" /> Scoped to the visible chat · never sends for you
                </div>
              )}
            </header>

            <div className="relative min-h-0 flex-1 bg-gradient-to-b from-black/35 via-black/10 to-black/45 md:bg-none">
              <div className="h-full overflow-y-auto px-4 pb-44 pt-5 md:px-5 md:pb-8">
                {!messages.length && !visibleActions.length ? (
                  <div className="flex min-h-full flex-col justify-end pb-8 md:justify-center md:pb-10">
                    <h3 className="max-w-xs text-2xl font-medium tracking-[-0.03em] text-white">{isPrivateChatMode ? 'Help with this conversation' : 'What should we work on?'}</h3>
                    <p className="mt-3 max-w-sm text-sm leading-6 text-white/42">{isPrivateChatMode ? 'Rewrite, translate, summarize, or prepare a reply from only the context you opened.' : 'Ask about your products, sales, invoices, communities, files, or workspace. Any change that needs approval stays a reviewable draft.'}</p>
                    {isPrivateChatMode && context.chatAiIntroSeen !== true && !dismissedChatIntro && (
                      <button type="button" onClick={() => { setDismissedChatIntro(true); window.dispatchEvent(new CustomEvent('wersee:chat-ai-intro-seen')); }} className="mt-4 w-fit rounded-full border border-emerald-300/15 bg-emerald-300/[0.07] px-3 py-2 text-xs font-semibold text-emerald-100">Understood</button>
                    )}
                    <div className="mt-6 flex flex-wrap gap-2">
                      {(isPrivateChatMode ? CHAT_AI_ACTIONS.slice(0, 3).map((action) => ({ label: action.label, prompt: action.prompt })) : [
                        { label: 'Recent sales', prompt: 'Show my recent sales' },
                        { label: 'Check listings', prompt: 'Check my product listings for missing details' },
                        { label: 'Draft a product', prompt: 'Create a draft product from an idea' },
                      ]).map((suggestion) => (
                        <button key={suggestion.label} onClick={() => void sendPrompt(suggestion.prompt)} disabled={isRunning} className="rounded-full border border-white/[0.09] bg-black/35 px-3 py-2 text-xs font-medium text-white/62 backdrop-blur-xl transition hover:bg-white/[0.08] hover:text-white disabled:opacity-40">{suggestion.label}</button>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {messages.filter((message) => message.role === 'user' || message.content.trim()).map((message) => (
                      <div key={message.id} className={`${message.id === mobileResponseId ? 'hidden md:flex' : 'flex'} ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={message.role === 'user'
                          ? 'max-w-[86%] rounded-[22px] rounded-br-md bg-white px-4 py-2.5 text-sm leading-6 text-black shadow-lg'
                          : 'min-w-0 max-w-[94%] rounded-[24px] border border-white/[0.08] bg-black/38 px-4 py-3 text-sm leading-6 text-white/78 backdrop-blur-xl md:max-w-full md:border-0 md:bg-transparent md:px-0 md:py-0'}>
                          {message.role === 'assistant' ? (
                            <>
                              {message.content ? <div className="prose prose-invert prose-sm max-w-none prose-p:my-2 prose-ul:my-2 prose-pre:overflow-x-auto"><ReactMarkdown>{message.content}</ReactMarkdown></div> : null}
                              {isPrivateChatMode && message.content.trim() && (
                                <div className="mt-3 flex flex-wrap gap-2">
                                  <button type="button" onClick={() => { window.dispatchEvent(new CustomEvent('wersee:chat-ai-use-draft', { detail: { text: message.content.trim() } })); onClose(); }} className="rounded-full bg-white px-3 py-2 text-xs font-bold text-black">Use in chat</button>
                                  <button type="button" onClick={() => void navigator.clipboard.writeText(message.content.trim())} className="flex items-center gap-1.5 rounded-full border border-white/10 px-3 py-2 text-xs font-semibold text-white/65"><Copy className="h-3.5 w-3.5" /> Copy</button>
                                </div>
                              )}
                            </>
                          ) : message.content}
                        </div>
                      </div>
                    ))}
                    {visibleActions.map((action) => <ActionCard key={action.id} action={action} busy={actionBusy === action.id} onApprove={() => mutateAction(action.id, 'approve')} onReject={() => mutateAction(action.id, 'reject')} onUndo={() => mutateAction(action.id, 'undo')} onOpen={(route) => onNavigate?.(route)} />)}
                    {error && <div className="rounded-[22px] border border-rose-400/20 bg-rose-400/[0.08] p-3 backdrop-blur-xl"><div className="flex gap-2 text-sm text-rose-100"><XCircle className="mt-0.5 h-4 w-4 shrink-0" /><span>{error.message}</span></div>{error.retryable && lastPrompt && <button onClick={() => void sendPrompt(lastPrompt)} className="mt-2 flex items-center gap-1.5 text-xs font-semibold text-rose-100"><Redo2 className="h-3.5 w-3.5" /> Try again</button>}</div>}
                    <AnimatePresence initial={false}>
                      {(isRunning || mobileResult) && (
                        <motion.div
                          layout
                          initial={{ opacity: 0, y: 14, scale: 0.97 }}
                          animate={{ opacity: 1, y: 0, scale: 1 }}
                          exit={{ opacity: 0, y: 8, scale: 0.98 }}
                          className="origin-top pt-2 md:hidden"
                        >
                          <CodexExpandableActivityPill
                            active={isRunning}
                            toolName={activeToolName}
                            label={activityLabel}
                            detail={!isRunning && mobileResult ? (
                              <div className="custom-scrollbar max-h-[38dvh] overflow-y-auto pr-1">
                                <div className="prose prose-invert prose-sm prose-p:my-2 prose-ul:my-2 prose-pre:overflow-x-auto">
                                  <ReactMarkdown>{mobileResult}</ReactMarkdown>
                                </div>
                                {isPrivateChatMode && mobileAssistantMessage?.content.trim() && (
                                  <div className="mt-3 flex flex-wrap gap-2">
                                    <button type="button" onClick={() => { window.dispatchEvent(new CustomEvent('wersee:chat-ai-use-draft', { detail: { text: mobileAssistantMessage.content.trim() } })); onClose(); }} className="rounded-full bg-white px-3 py-2 text-xs font-bold text-black">Use in chat</button>
                                    <button type="button" onClick={() => void navigator.clipboard.writeText(mobileAssistantMessage.content.trim())} className="flex items-center gap-1.5 rounded-full border border-white/10 px-3 py-2 text-xs font-semibold text-white/65"><Copy className="h-3.5 w-3.5" /> Copy</button>
                                  </div>
                                )}
                              </div>
                            ) : undefined}
                          />
                        </motion.div>
                      )}
                    </AnimatePresence>
                    <div ref={endRef} />
                  </div>
                )}
              </div>

              <AnimatePresence>
                {showHistory && <motion.div className="absolute inset-0 z-40 overflow-y-auto bg-[#09090b]/95 p-4 pt-[max(16px,env(safe-area-inset-top))] backdrop-blur-3xl md:p-5" initial={{ x: '-18%', opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: '-18%', opacity: 0 }}><div className="mb-4 flex items-center"><button onClick={() => setShowHistory(false)} className="mr-2 rounded-full p-2 text-white/45 hover:bg-white/5"><ChevronLeft className="h-4 w-4" /></button><div className="flex-1"><h3 className="font-semibold">Conversations</h3><p className="text-xs text-white/35">Private to your account</p></div><button onClick={newConversation} className="flex items-center gap-1.5 rounded-full bg-white px-3 py-2 text-xs font-semibold text-black"><MessageSquarePlus className="h-3.5 w-3.5" /> New</button></div><div className="space-y-1">{conversations.map((conversation) => <div key={conversation.id} className={`group flex items-center rounded-[20px] transition ${conversation.id === conversationId ? 'bg-white/[0.1] text-white' : 'text-white/70 hover:bg-white/5'}`}><button onClick={() => void loadConversation(conversation.id)} className="min-w-0 flex-1 p-3 text-left"><p className="truncate text-sm font-medium">{conversation.title}</p><p className="mt-1 flex items-center gap-1.5 text-[10px] text-white/30"><Clock3 className="h-3 w-3" /> {new Date(conversation.updated_at).toLocaleString()}</p></button><button onClick={() => void deleteConversation(conversation.id)} className="mr-2 rounded-full p-2 text-white/25 opacity-0 hover:bg-rose-400/10 hover:text-rose-300 group-hover:opacity-100 focus:opacity-100" aria-label={`Delete ${conversation.title}`}><Trash2 className="h-3.5 w-3.5" /></button></div>)}{!conversations.length && <p className="py-12 text-center text-sm text-white/35">No conversations yet.</p>}</div></motion.div>}
              </AnimatePresence>
              <AnimatePresence>
                {showActivity && <motion.div className="absolute inset-0 z-40 overflow-y-auto bg-[#09090b]/95 p-4 pt-[max(16px,env(safe-area-inset-top))] backdrop-blur-3xl md:p-5" initial={{ x: '-18%', opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: '-18%', opacity: 0 }}><div className="mb-4 flex items-center"><button onClick={() => setShowActivity(false)} className="mr-2 rounded-full p-2 text-white/45 hover:bg-white/5"><ChevronLeft className="h-4 w-4" /></button><div><h3 className="font-semibold">Activity</h3><p className="text-xs text-white/35">Your private AI action trail</p></div></div><div className="space-y-2">{activity.map((entry) => <div key={entry.id} className="rounded-[20px] border border-white/[0.08] bg-white/[0.035] p-3"><div className="flex items-center justify-between gap-3"><p className="truncate text-sm font-medium text-white/75">{entry.tool_name || entry.event_type}</p><span className={`rounded-full px-2 py-0.5 text-[9px] uppercase ${entry.status === 'completed' ? 'bg-emerald-400/10 text-emerald-300' : entry.status === 'failed' ? 'bg-rose-400/10 text-rose-300' : 'bg-white/5 text-white/40'}`}>{entry.status}</span></div><p className="mt-1 text-[10px] text-white/28">{entry.event_type} · {new Date(entry.created_at).toLocaleString()}</p></div>)}{!activity.length && <p className="py-12 text-center text-sm text-white/35">No AI activity yet.</p>}</div></motion.div>}
              </AnimatePresence>
            </div>

            <footer className="absolute inset-x-0 bottom-0 z-30 bg-gradient-to-t from-black via-black/82 to-transparent px-3 pb-[max(10px,env(safe-area-inset-bottom))] pt-8 md:relative md:shrink-0 md:border-t md:border-white/[0.07] md:bg-[#09090b] md:px-4 md:pb-4 md:pt-3">
              <CodexComposer
                value={prompt}
                onChange={setPrompt}
                onSubmit={() => void sendPrompt()}
                onStop={() => void stopRun()}
                disabled={isRunning}
                working={isRunning}
                reasoningLabel={stepLabel || humanizeAiTool(activeToolName)}
                toolName={activeToolName}
                placeholder={isPrivateChatMode ? 'Ask about this chat…' : 'Ask Wersee AI…'}
                menuItems={composerMenuItems}
                textareaRef={textareaRef}
              />
            </footer>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
};
