import React, { useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import {
  BarChart3,
  Check,
  ImageIcon,
  Loader2,
  Package,
  Plus,
  Search,
  ShieldCheck,
  Trash2,
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BottomSheetModal } from '../ui/BottomSheetModal';

export type ChatProductSnapshot = {
  id: string;
  title: string;
  description?: string;
  price?: number;
  currency?: string;
  imageUrl?: string;
};

type ListingRow = {
  id: string;
  title: string;
  description?: string | null;
  price?: number | string | null;
  currency?: string | null;
  image_url?: string | null;
  images?: string[] | null;
  status?: string | null;
};

const money = (value?: number, currency = 'EUR') => {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency: currency.toUpperCase(),
  }).format(value);
};

export function ChatProductPickerModal({
  isOpen,
  onClose,
  userId,
  onSelect,
}: {
  isOpen: boolean;
  onClose: () => void;
  userId?: string;
  onSelect: (product: ChatProductSnapshot) => void;
}) {
  const [products, setProducts] = useState<ListingRow[]>([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!isOpen || !userId) return;
    let active = true;
    setLoading(true);
    setError('');
    void supabase
      .from('listings')
      .select('id,title,description,price,currency,image_url,images,status')
      .eq('seller_id', userId)
      .order('updated_at', { ascending: false })
      .limit(100)
      .then(({ data, error: loadError }) => {
        if (!active) return;
        setLoading(false);
        if (loadError) {
          setError('Your products could not be loaded.');
          return;
        }
        setProducts((data || []) as ListingRow[]);
      });
    return () => {
      active = false;
    };
  }, [isOpen, userId]);

  const filtered = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return products;
    return products.filter((product) =>
      [product.title, product.description, product.status]
        .some((value) => value?.toLowerCase().includes(normalized)),
    );
  }, [products, query]);

  return (
    <BottomSheetModal isOpen={isOpen} onClose={onClose} title="Add a product to chat" maxWidth="max-w-3xl">
      <div className="p-4 md:p-6">
        <div className="mb-5 flex items-start gap-3 rounded-2xl border border-emerald-400/15 bg-emerald-400/[0.055] p-3.5">
          <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-emerald-300" />
          <div>
            <p className="text-sm font-semibold text-emerald-100">Encrypted chat card</p>
            <p className="mt-1 text-xs leading-5 text-emerald-100/55">
              The selected product snapshot is encrypted in the message and visible only to chat members.
            </p>
          </div>
        </div>

        <label className="flex h-12 items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.04] px-4 focus-within:border-indigo-400/35">
          <Search className="h-4 w-4 text-white/35" />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search your products"
            className="min-w-0 flex-1 bg-transparent text-sm text-white outline-none placeholder:text-white/25"
          />
        </label>

        <div className="mt-4 grid max-h-[52vh] gap-2 overflow-y-auto pr-1 sm:grid-cols-2">
          {loading && (
            <div className="col-span-full flex items-center justify-center gap-2 py-14 text-sm text-white/40">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading your products…
            </div>
          )}
          {!loading && error && (
            <div className="col-span-full rounded-2xl border border-rose-400/15 bg-rose-400/[0.05] px-4 py-10 text-center text-sm text-rose-200/70">
              {error}
            </div>
          )}
          {!loading && !error && filtered.map((product) => {
            const imageUrl = product.image_url || product.images?.[0] || undefined;
            const price = Number(product.price);
            const formattedPrice = money(Number.isFinite(price) ? price : undefined, product.currency || 'EUR');
            return (
              <motion.button
                type="button"
                key={product.id}
                whileTap={{ scale: 0.985 }}
                onClick={() => {
                  onSelect({
                    id: product.id,
                    title: product.title,
                    description: product.description || undefined,
                    price: Number.isFinite(price) ? price : undefined,
                    currency: product.currency || 'EUR',
                    imageUrl,
                  });
                  onClose();
                }}
                className="group flex min-h-24 items-center gap-3 rounded-[22px] border border-white/8 bg-white/[0.025] p-3 text-left transition hover:border-indigo-400/25 hover:bg-indigo-400/[0.055]"
              >
                <span className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-2xl bg-white/5">
                  {imageUrl
                    ? <img src={imageUrl} alt="" className="h-full w-full object-cover" />
                    : <ImageIcon className="h-5 w-5 text-white/20" />}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-bold text-white">{product.title}</span>
                  <span className="mt-1 block truncate text-xs text-white/35">{formattedPrice || 'Price unavailable'}</span>
                  <span className="mt-2 inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-[0.12em] text-indigo-300">
                    <Plus className="h-3 w-3" /> Add to chat
                  </span>
                </span>
              </motion.button>
            );
          })}
          {!loading && !error && filtered.length === 0 && (
            <div className="col-span-full rounded-2xl border border-dashed border-white/10 px-5 py-14 text-center">
              <Package className="mx-auto h-6 w-6 text-white/20" />
              <p className="mt-3 text-sm font-semibold text-white/55">No matching products</p>
              <p className="mt-1 text-xs text-white/25">Only your real Wersee listings appear here.</p>
            </div>
          )}
        </div>
      </div>
    </BottomSheetModal>
  );
}

export type ChatPollDraft = {
  question: string;
  options: string[];
  allowMultiple: boolean;
};

export function ChatPollComposerModal({
  isOpen,
  onClose,
  onCreate,
}: {
  isOpen: boolean;
  onClose: () => void;
  onCreate: (poll: ChatPollDraft) => void;
}) {
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '']);
  const [allowMultiple, setAllowMultiple] = useState(false);
  const cleanOptions = options.map((option) => option.trim()).filter(Boolean);
  const canCreate = question.trim().length >= 3 && cleanOptions.length >= 2;

  const reset = () => {
    setQuestion('');
    setOptions(['', '']);
    setAllowMultiple(false);
  };

  return (
    <BottomSheetModal isOpen={isOpen} onClose={onClose} title="Create a poll" maxWidth="max-w-xl">
      <div className="p-4 md:p-6">
        <div className="mb-5 flex items-start gap-3 rounded-2xl border border-violet-400/15 bg-violet-400/[0.055] p-3.5">
          <BarChart3 className="mt-0.5 h-4 w-4 shrink-0 text-violet-300" />
          <div>
            <p className="text-sm font-semibold text-violet-100">Encrypted chat poll</p>
            <p className="mt-1 text-xs leading-5 text-violet-100/55">
              The question and choices stay in the encrypted message. Vote access is limited to chat members.
            </p>
          </div>
        </div>

        <label className="block">
          <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/35">Question</span>
          <input
            autoFocus
            maxLength={180}
            value={question}
            onChange={(event) => setQuestion(event.target.value.replace(/\r?\n/g, ' '))}
            placeholder="What should we choose?"
            className="mt-2 h-13 w-full rounded-2xl border border-white/10 bg-white/[0.04] px-4 text-sm text-white outline-none placeholder:text-white/25 focus:border-violet-400/35"
          />
        </label>

        <div className="mt-5 space-y-2">
          <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/35">Choices</span>
          <AnimatePresence initial={false}>
            {options.map((option, index) => (
              <motion.div
                layout
                key={index}
                initial={{ opacity: 0, y: -6 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.96 }}
                className="flex items-center gap-2"
              >
                <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white/5 text-xs font-bold text-white/35">{index + 1}</span>
                <input
                  maxLength={90}
                  value={option}
                  onChange={(event) => setOptions((current) =>
                    current.map((item, itemIndex) => itemIndex === index ? event.target.value.replace(/\r?\n/g, ' ') : item),
                  )}
                  placeholder={`Choice ${index + 1}`}
                  className="h-12 min-w-0 flex-1 rounded-2xl border border-white/10 bg-white/[0.04] px-4 text-sm text-white outline-none placeholder:text-white/25 focus:border-violet-400/35"
                />
                {options.length > 2 && (
                  <button
                    type="button"
                    onClick={() => setOptions((current) => current.filter((_, itemIndex) => itemIndex !== index))}
                    className="grid h-10 w-10 place-items-center rounded-xl text-white/30 hover:bg-rose-400/10 hover:text-rose-300"
                    aria-label={`Remove choice ${index + 1}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                )}
              </motion.div>
            ))}
          </AnimatePresence>
          {options.length < 8 && (
            <button
              type="button"
              onClick={() => setOptions((current) => [...current, ''])}
              className="mt-2 flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-semibold text-violet-300 hover:bg-violet-400/[0.07]"
            >
              <Plus className="h-4 w-4" /> Add a choice
            </button>
          )}
        </div>

        <div className="mt-5 flex items-center justify-between gap-4 rounded-2xl border border-white/8 bg-white/[0.025] p-4">
          <span>
            <span className="block text-sm font-semibold text-white">Allow multiple choices</span>
            <span className="mt-1 block text-xs text-white/35">People can select more than one answer.</span>
          </span>
          <button
            type="button"
            role="switch"
            aria-checked={allowMultiple}
            onClick={() => setAllowMultiple((value) => !value)}
            className={`relative h-7 w-12 rounded-full transition ${allowMultiple ? 'bg-violet-500' : 'bg-white/10'}`}
          >
            <motion.span
              animate={{ x: allowMultiple ? 22 : 3 }}
              className="absolute left-0 top-1 grid h-5 w-5 place-items-center rounded-full bg-white text-violet-600 shadow"
            >
              {allowMultiple && <Check className="h-3 w-3" />}
            </motion.span>
          </button>
        </div>

        <button
          type="button"
          disabled={!canCreate}
          onClick={() => {
            onCreate({ question: question.trim(), options: cleanOptions, allowMultiple });
            reset();
            onClose();
          }}
          className="mt-6 h-12 w-full rounded-2xl bg-white text-sm font-bold text-black transition hover:bg-zinc-200 disabled:bg-white/8 disabled:text-white/25"
        >
          Send poll
        </button>
      </div>
    </BottomSheetModal>
  );
}
