import React, {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';
import type { LucideIcon } from 'lucide-react';
import {
  ArrowLeft,
  BookOpen,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Clock3,
  Download,
  ExternalLink,
  FileText,
  GraduationCap,
  Headphones,
  Layers3,
  Link2,
  Loader2,
  LockKeyhole,
  Menu,
  MessageCircle,
  PackageOpen,
  Pencil,
  Play,
  Send,
  Settings2,
  Share2,
  Trophy,
  Video,
  X,
} from 'lucide-react';
import type { CourseBuilderData, Lesson } from '../dashboard/CourseBuilder';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import { appToast } from '@/lib/feedback';
import { PdfViewer } from './PdfViewer';
import { VideoPlayer } from './VideoPlayer';
import { DigitalProductAccess } from './DigitalProductAccess';
import { VirtualItemAccess } from './VirtualItemAccess';
import { Asset3DAccess } from './Asset3DAccess';
import {
  flattenCourseLessons,
  getCourseBuilderData,
  getLessonMediaSource,
  isCourseListing,
} from './courseAccessModel';

const LazyCourseBuilder = lazy(() => import('../dashboard/CourseBuilder').then((module) => ({
  default: module.CourseBuilder,
})));

interface AccessContentProps {
  listingId: string;
  onClose: () => void;
  onEditListing?: () => void;
}

interface LessonComment {
  id: string;
  content: string;
  created_at: string;
  user_name?: string | null;
  user_avatar?: string | null;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const safeAccent = (value: unknown) => (
  typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value : '#7c3aed'
);

const withAlpha = (hex: string, alpha: string) => `${hex}${alpha}`;

const initials = (name: string) => name
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 2)
  .map((part) => part[0]?.toUpperCase())
  .join('') || 'W';

const lessonIcon = (type: Lesson['type']): LucideIcon => {
  if (type === 'video') return Video;
  if (type === 'audio') return Headphones;
  if (type === 'link') return Link2;
  return FileText;
};

const lessonLabel = (type: Lesson['type']) => {
  if (type === 'video') return 'Video lesson';
  if (type === 'audio') return 'Audio lesson';
  if (type === 'pdf') return 'Document';
  if (type === 'link') return 'External link';
  if (type === 'quiz') return 'Quiz';
  return 'Lesson';
};

export const AccessContent: React.FC<AccessContentProps> = ({
  listingId,
  onClose,
  onEditListing,
}) => {
  const { user } = useAuth();
  const userId = user?.id;
  const [listing, setListing] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [activeLessonId, setActiveLessonId] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(() => (
    typeof window !== 'undefined' && window.innerWidth >= 1024
  ));
  const [editorOpen, setEditorOpen] = useState(false);
  const [progress, setProgress] = useState<string[]>([]);
  const [points, setPoints] = useState(0);
  const [comments, setComments] = useState<LessonComment[]>([]);
  const [commentsLoading, setCommentsLoading] = useState(false);
  const [commentsError, setCommentsError] = useState('');
  const [discussionOpen, setDiscussionOpen] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [postingComment, setPostingComment] = useState(false);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, number>>({});

  const courseData = useMemo(
    () => getCourseBuilderData(listing?.metadata),
    [listing?.metadata],
  );
  const modules = courseData.modules || [];
  const lessonLocations = useMemo(() => flattenCourseLessons(modules), [modules]);
  const lessonIds = useMemo(
    () => new Set(lessonLocations.map(({ lesson }) => lesson.id)),
    [lessonLocations],
  );
  const activeIndex = lessonLocations.findIndex(({ lesson }) => lesson.id === activeLessonId);
  const activeLocation = activeIndex >= 0 ? lessonLocations[activeIndex] : null;
  const activeLesson = activeLocation?.lesson || null;
  const previousLesson = activeIndex > 0 ? lessonLocations[activeIndex - 1]?.lesson || null : null;
  const nextLesson = activeIndex >= 0 ? lessonLocations[activeIndex + 1]?.lesson || null : null;
  const completedLessons = progress.filter((lessonId) => lessonIds.has(lessonId)).length;
  const completionPercentage = lessonLocations.length
    ? Math.min(100, Math.round((completedLessons / lessonLocations.length) * 100))
    : 0;
  const isOwner = Boolean(userId && listing?.seller_id === userId);
  const courseSettings = courseData.settings;
  const commentsEnabled = courseSettings?.commentsEnabled !== false;
  const gamificationEnabled = courseSettings?.gamificationEnabled === true;
  const accent = safeAccent(courseData.design?.primaryColor);

  const resolveUrl = useCallback((path: string, type: Lesson['type']) => {
    if (!path) return '';
    if (/^(https?:|blob:|data:)/i.test(path)) return path;

    const bucket = type === 'video' || type === 'audio' ? 'course-videos' : 'course-content';
    return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl;
  }, []);

  const mediaUrl = useMemo(
    () => resolveUrl(getLessonMediaSource(activeLesson), activeLesson?.type || 'text'),
    [activeLesson, resolveUrl],
  );

  useEffect(() => {
    const handleResize = () => setSidebarOpen(window.innerWidth >= 1024);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    let cancelled = false;

    const fetchAccess = async () => {
      setLoading(true);
      setLoadError('');

      if (!UUID_PATTERN.test(listingId)) {
        setLoadError('This course link is invalid.');
        setLoading(false);
        return;
      }

      try {
        const { data: listingData, error: listingError } = await supabase
          .from('listings')
          .select('*')
          .eq('id', listingId)
          .single();

        if (listingError) throw listingError;
        if (!listingData) throw new Error('COURSE_NOT_FOUND');
        if (cancelled) return;

        if (!userId) {
          setListing({ ...listingData, noAccess: true });
          return;
        }

        if (listingData.seller_id !== userId) {
          const { data: directOrder } = await supabase
            .from('orders')
            .select('id')
            .eq('buyer_id', userId)
            .eq('listing_id', listingId)
            .maybeSingle();

          let hasAccess = Boolean(directOrder);

          if (!hasAccess) {
            const { data: bundleItems } = await supabase
              .from('bundle_items')
              .select('bundle_id')
              .eq('product_id', listingId);
            const bundleIds = (bundleItems || []).map((item) => item.bundle_id);

            if (bundleIds.length) {
              const { data: bundleOrder } = await supabase
                .from('orders')
                .select('id')
                .eq('buyer_id', userId)
                .in('listing_id', bundleIds)
                .limit(1);
              hasAccess = Boolean(bundleOrder?.length);
            }
          }

          if (!hasAccess && listingData.seller_id && listingData.category) {
            const { data: allAccessBundles } = await supabase
              .from('listings')
              .select('id')
              .eq('seller_id', listingData.seller_id)
              .eq('type', 'bundle')
              .contains('metadata', {
                is_all_access: true,
                all_access_category: listingData.category,
              });
            const allAccessIds = (allAccessBundles || []).map((bundle) => bundle.id);

            if (allAccessIds.length) {
              const { data: allAccessOrder } = await supabase
                .from('orders')
                .select('id')
                .eq('buyer_id', userId)
                .in('listing_id', allAccessIds)
                .limit(1);
              hasAccess = Boolean(allAccessOrder?.length);
            }
          }

          if (!hasAccess) {
            setListing({ ...listingData, noAccess: true });
            return;
          }
        }

        if (cancelled) return;
        setListing(listingData);

        const { data: progressData } = await supabase
          .from('course_progress')
          .select('completed_lessons, points')
          .eq('user_id', userId)
          .eq('listing_id', listingId)
          .maybeSingle();

        if (!cancelled && progressData) {
          setProgress(Array.isArray(progressData.completed_lessons) ? progressData.completed_lessons : []);
          setPoints(Number(progressData.points) || 0);
        }
      } catch (error) {
        console.error('Course access could not be loaded:', error);
        if (!cancelled) setLoadError('This course could not be loaded right now.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    void fetchAccess();
    return () => {
      cancelled = true;
    };
  }, [listingId, userId]);

  useEffect(() => {
    if (!lessonLocations.length) {
      setActiveLessonId(null);
      return;
    }

    setActiveLessonId((current) => (
      current && lessonIds.has(current) ? current : lessonLocations[0]?.lesson.id || null
    ));
  }, [lessonIds, lessonLocations]);

  useEffect(() => {
    setQuizAnswers({});
    setDiscussionOpen(false);

    if (!activeLessonId || !commentsEnabled) {
      setComments([]);
      return;
    }

    let cancelled = false;
    setCommentsLoading(true);
    setCommentsError('');

    void (async () => {
      const { data, error } = await supabase
        .from('lesson_comments')
        .select('id, content, created_at, user_name, user_avatar')
        .eq('listing_id', listingId)
        .eq('lesson_id', activeLessonId)
        .order('created_at', { ascending: false });

      if (cancelled) return;
      if (error) {
        setCommentsError('Discussion is temporarily unavailable.');
        setComments([]);
      } else {
        setComments((data || []) as LessonComment[]);
      }
      setCommentsLoading(false);
    })();

    return () => {
      cancelled = true;
    };
  }, [activeLessonId, commentsEnabled, listingId]);

  const selectLesson = (lessonId: string) => {
    setActiveLessonId(lessonId);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const toggleLessonCompletion = async () => {
    if (!userId || !activeLesson || isOwner) return;

    const wasCompleted = progress.includes(activeLesson.id);
    const nextProgress = wasCompleted
      ? progress.filter((lessonId) => lessonId !== activeLesson.id)
      : [...progress, activeLesson.id];
    const nextPoints = gamificationEnabled
      ? Math.max(0, points + (wasCompleted ? -10 : 10))
      : points;

    setProgress(nextProgress);
    setPoints(nextPoints);

    const { error } = await supabase
      .from('course_progress')
      .upsert({
        user_id: userId,
        listing_id: listingId,
        completed_lessons: nextProgress,
        points: nextPoints,
        last_accessed: new Date().toISOString(),
      });

    if (error) {
      setProgress(progress);
      setPoints(points);
      console.error('Course progress could not be saved:', error);
      appToast('Your progress could not be saved. Please try again.');
    }
  };

  const handlePostComment = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!user || !activeLesson || !newComment.trim() || postingComment) return;

    setPostingComment(true);
    const userName = user.user_metadata?.full_name
      || user.user_metadata?.name
      || user.email?.split('@')[0]
      || 'Wersee member';
    const userAvatar = user.user_metadata?.avatar_url || user.user_metadata?.picture || '';

    const { data, error } = await supabase
      .from('lesson_comments')
      .insert({
        listing_id: listingId,
        lesson_id: activeLesson.id,
        user_id: user.id,
        user_name: userName,
        user_avatar: userAvatar,
        content: newComment.trim(),
      })
      .select('id, content, created_at, user_name, user_avatar')
      .single();

    setPostingComment(false);
    if (error || !data) {
      console.error('Comment could not be posted:', error);
      appToast('Your comment could not be posted. Please try again.');
      return;
    }

    setComments((current) => [data as LessonComment, ...current]);
    setNewComment('');
  };

  const handleShare = async () => {
    const url = window.location.href;
    try {
      if (navigator.share) {
        await navigator.share({ title: listing?.title || 'Wersee course', url });
      } else {
        await navigator.clipboard.writeText(url);
        appToast('Course link copied.');
      }
    } catch (error) {
      if ((error as DOMException)?.name !== 'AbortError') {
        appToast('The course link could not be shared.');
      }
    }
  };

  const handleSaveCourse = async (data: CourseBuilderData) => {
    if (!userId || !listing || !isOwner) throw new Error('COURSE_OWNER_REQUIRED');

    const currentMetadata = listing.metadata && typeof listing.metadata === 'object'
      ? listing.metadata
      : {};
    const currentCourse = currentMetadata.course && typeof currentMetadata.course === 'object'
      ? currentMetadata.course
      : {};
    const nextMetadata: Record<string, unknown> = {
      ...currentMetadata,
      course: { ...currentCourse, ...data },
      curriculum: data.modules,
    };

    if (Array.isArray(currentMetadata.modules)) nextMetadata.modules = data.modules;

    const { data: updatedListing, error } = await supabase
      .from('listings')
      .update({ metadata: nextMetadata })
      .eq('id', listingId)
      .eq('seller_id', userId)
      .select('*')
      .single();

    if (error || !updatedListing) throw error || new Error('COURSE_UPDATE_EMPTY');

    setListing(updatedListing);
    setEditorOpen(false);
    appToast('Course saved. The viewer is up to date.');
  };

  if (loading) {
    return (
      <div className="flex h-full min-h-[420px] items-center justify-center bg-[#080808] text-white">
        <div className="flex items-center gap-3 rounded-full border border-white/10 bg-white/[0.04] px-4 py-2.5 text-sm text-white/70">
          <Loader2 className="h-4 w-4 animate-spin" />
          Loading course
        </div>
      </div>
    );
  }

  if (loadError || !listing) {
    return (
      <div className="flex h-full min-h-[420px] flex-col items-center justify-center bg-[#080808] px-6 text-center text-white">
        <div className="mb-5 flex h-14 w-14 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.04]">
          <PackageOpen className="h-6 w-6 text-white/45" />
        </div>
        <h2 className="text-xl font-semibold">Course unavailable</h2>
        <p className="mt-2 max-w-sm text-sm leading-6 text-white/45">{loadError || 'This course could not be found.'}</p>
        <button type="button" onClick={onClose} className="mt-6 rounded-full bg-white px-5 py-2.5 text-sm font-semibold text-black">
          Back to dashboard
        </button>
      </div>
    );
  }

  if (listing.noAccess) {
    return (
      <div className="flex h-full min-h-[420px] flex-col items-center justify-center bg-[#080808] px-6 text-center text-white">
        <div className="mb-5 flex h-14 w-14 items-center justify-center rounded-2xl border border-amber-400/20 bg-amber-400/10">
          <LockKeyhole className="h-6 w-6 text-amber-300" />
        </div>
        <h2 className="text-xl font-semibold">Purchase required</h2>
        <p className="mt-2 max-w-sm text-sm leading-6 text-white/45">This product is not available in your library yet.</p>
        <button type="button" onClick={onClose} className="mt-6 rounded-full bg-white px-5 py-2.5 text-sm font-semibold text-black">
          Back to dashboard
        </button>
      </div>
    );
  }

  const type = String(listing.type || '').toLowerCase();
  const category = String(listing.category || '').toLowerCase();
  const isCourse = isCourseListing(listing);
  const isVirtual = type === 'virtual' || category === 'virtual item';
  const isAsset3D = type === 'asset_3d' || category === '3d assets';
  const isDigital = type === 'digital' || type === 'digital_product' || category === 'digital product';

  if (isAsset3D) return <Asset3DAccess listing={listing} onClose={onClose} />;
  if (isVirtual) return <VirtualItemAccess listing={listing} onClose={onClose} />;
  if (isDigital && !isCourse) return <DigitalProductAccess listing={listing} onClose={onClose} />;

  const ActiveLessonIcon = activeLesson ? lessonIcon(activeLesson.type) : BookOpen;
  const quiz = activeLesson?.quiz || [];

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden bg-[#080808] text-white" data-testid="course-viewer">
      <header className="flex h-16 shrink-0 items-center justify-between gap-3 border-b border-white/[0.07] bg-[#0a0a0a]/95 px-3 backdrop-blur-xl sm:px-5">
        <div className="flex min-w-0 items-center gap-2 sm:gap-3">
          <button
            type="button"
            onClick={onClose}
            aria-label="Back to dashboard"
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] text-white/60 transition hover:bg-white/[0.09] hover:text-white"
          >
            <ArrowLeft className="h-4 w-4" />
          </button>
          <button
            type="button"
            onClick={() => setSidebarOpen(true)}
            className="flex h-9 items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 text-xs font-semibold text-white/75 lg:hidden"
          >
            <Menu className="h-4 w-4" />
            Lessons
          </button>
          <div className="hidden min-w-0 sm:block">
            <p className="max-w-[34vw] truncate text-sm font-semibold">{listing.title || 'Untitled course'}</p>
            <p className="text-[11px] text-white/35">Course viewer</p>
          </div>
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {isOwner ? (
            <>
              <span className="hidden rounded-full border border-violet-400/20 bg-violet-400/10 px-3 py-2 text-[11px] font-semibold text-violet-200 sm:inline-flex">
                Owner preview
              </span>
              <button
                type="button"
                onClick={() => setEditorOpen(true)}
                className="flex h-9 items-center gap-2 rounded-full px-3.5 text-xs font-semibold text-white shadow-lg transition hover:brightness-110"
                style={{ backgroundColor: accent }}
              >
                <Pencil className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">Edit course</span>
                <span className="sm:hidden">Edit</span>
              </button>
            </>
          ) : (
            <span className="flex h-9 items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 text-xs font-semibold text-white/70">
              <CheckCircle2 className="h-3.5 w-3.5" style={{ color: accent }} />
              {completionPercentage}%
            </span>
          )}
          <button
            type="button"
            onClick={() => void handleShare()}
            aria-label="Share course"
            className="flex h-9 w-9 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] text-white/55 transition hover:bg-white/[0.09] hover:text-white"
          >
            <Share2 className="h-4 w-4" />
          </button>
        </div>
      </header>

      <div className="relative flex min-h-0 flex-1 overflow-hidden">
        {sidebarOpen ? (
          <>
            <button
              type="button"
              aria-label="Close curriculum"
              onClick={() => setSidebarOpen(false)}
              className="absolute inset-0 z-40 bg-black/65 backdrop-blur-sm lg:hidden"
            />
            <aside className="absolute inset-y-0 left-0 z-50 flex w-[min(88vw,320px)] shrink-0 flex-col border-r border-white/[0.07] bg-[#0d0d0d] shadow-2xl lg:static lg:z-auto lg:w-[310px] lg:shadow-none">
              <div className="border-b border-white/[0.07] p-4">
                <div className="flex items-start gap-3">
                  <div
                    className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border"
                    style={{
                      backgroundColor: withAlpha(accent, '18'),
                      borderColor: withAlpha(accent, '35'),
                      color: accent,
                    }}
                  >
                    <GraduationCap className="h-5 w-5" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <h2 className="truncate text-sm font-semibold">{listing.title || 'Untitled course'}</h2>
                    <div className="mt-1.5 flex flex-wrap gap-1.5">
                      <span className="rounded-full bg-white/[0.055] px-2 py-1 text-[10px] font-medium text-white/45">
                        {modules.length} {modules.length === 1 ? 'module' : 'modules'}
                      </span>
                      <span className="rounded-full bg-white/[0.055] px-2 py-1 text-[10px] font-medium text-white/45">
                        {lessonLocations.length} {lessonLocations.length === 1 ? 'lesson' : 'lessons'}
                      </span>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => setSidebarOpen(false)}
                    aria-label="Close curriculum"
                    className="rounded-full p-2 text-white/40 hover:bg-white/[0.07] hover:text-white lg:hidden"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>

                {!isOwner && lessonLocations.length ? (
                  <div className="mt-4 rounded-2xl border border-white/[0.07] bg-white/[0.025] p-3">
                    <div className="flex items-center justify-between text-[11px]">
                      <span className="font-medium text-white/45">Your progress</span>
                      <span className="font-semibold text-white/75">{completedLessons}/{lessonLocations.length}</span>
                    </div>
                    <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/[0.07]">
                      <div className="h-full rounded-full transition-all duration-500" style={{ width: `${completionPercentage}%`, backgroundColor: accent }} />
                    </div>
                  </div>
                ) : null}
              </div>

              <div className="min-h-0 flex-1 overflow-y-auto p-3">
                {modules.length ? (
                  <div className="space-y-4">
                    {modules.map((module, moduleIndex) => (
                      <section key={module.id}>
                        <div className="mb-2 flex items-center justify-between px-2">
                          <div className="min-w-0">
                            <p className="text-[9px] font-semibold uppercase tracking-[0.18em] text-white/28">Module {String(moduleIndex + 1).padStart(2, '0')}</p>
                            <h3 className="mt-1 truncate text-xs font-semibold text-white/70">{module.title}</h3>
                          </div>
                          <span className="ml-2 rounded-full bg-white/[0.05] px-2 py-1 text-[9px] font-semibold text-white/30">{module.lessons.length}</span>
                        </div>
                        <div className="space-y-1">
                          {module.lessons.map((lesson, lessonIndex) => {
                            const LessonIcon = lessonIcon(lesson.type);
                            const selected = activeLesson?.id === lesson.id;
                            const completed = progress.includes(lesson.id);
                            return (
                              <button
                                key={lesson.id}
                                type="button"
                                onClick={() => selectLesson(lesson.id)}
                                className={`group flex w-full items-center gap-3 rounded-2xl border px-2.5 py-2.5 text-left transition ${
                                  selected
                                    ? 'text-white shadow-lg shadow-black/20'
                                    : 'border-transparent text-white/48 hover:border-white/[0.06] hover:bg-white/[0.035] hover:text-white/80'
                                }`}
                                style={selected ? {
                                  backgroundColor: withAlpha(accent, '16'),
                                  borderColor: withAlpha(accent, '30'),
                                } : undefined}
                              >
                                <span
                                  className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-white/[0.07] bg-white/[0.04] text-white/40"
                                  style={selected ? { color: accent, borderColor: withAlpha(accent, '35') } : undefined}
                                >
                                  {completed ? <CheckCircle2 className="h-4 w-4 text-emerald-400" /> : <LessonIcon className="h-4 w-4" />}
                                </span>
                                <span className="min-w-0 flex-1">
                                  <span className="block truncate text-xs font-medium">{lesson.title}</span>
                                  <span className="mt-0.5 block text-[10px] text-white/28">
                                    {moduleIndex + 1}.{lessonIndex + 1} · {lesson.duration || lessonLabel(lesson.type)}
                                  </span>
                                </span>
                                {selected ? <ChevronRight className="h-3.5 w-3.5 shrink-0" style={{ color: accent }} /> : null}
                              </button>
                            );
                          })}
                        </div>
                      </section>
                    ))}
                  </div>
                ) : (
                  <div className="flex h-full min-h-64 flex-col items-center justify-center px-5 text-center">
                    <div className="flex h-12 w-12 items-center justify-center rounded-2xl border border-white/[0.07] bg-white/[0.035] text-white/30">
                      <Layers3 className="h-5 w-5" />
                    </div>
                    <h3 className="mt-4 text-sm font-semibold">{isOwner ? 'Build your curriculum' : 'Lessons are being prepared'}</h3>
                    <p className="mt-1.5 text-xs leading-5 text-white/35">
                      {isOwner ? 'Add modules, lessons and course media in the builder.' : 'The creator has not published any lessons yet.'}
                    </p>
                    {isOwner ? (
                      <button
                        type="button"
                        onClick={() => setEditorOpen(true)}
                        className="mt-5 rounded-full px-4 py-2 text-xs font-semibold text-white"
                        style={{ backgroundColor: accent }}
                      >
                        Start building
                      </button>
                    ) : null}
                  </div>
                )}
              </div>

              {isOwner ? (
                <div className="border-t border-white/[0.07] p-3">
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => setEditorOpen(true)}
                      className="flex items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.045] px-3 py-2.5 text-[11px] font-semibold text-white/70 hover:bg-white/[0.08] hover:text-white"
                    >
                      <Pencil className="h-3.5 w-3.5" /> Course
                    </button>
                    <button
                      type="button"
                      onClick={onEditListing}
                      disabled={!onEditListing}
                      className="flex items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.045] px-3 py-2.5 text-[11px] font-semibold text-white/70 hover:bg-white/[0.08] hover:text-white disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      <Settings2 className="h-3.5 w-3.5" /> Product
                    </button>
                  </div>
                </div>
              ) : null}
            </aside>
          </>
        ) : null}

        <main className="min-w-0 flex-1 overflow-y-auto bg-[radial-gradient(circle_at_top_right,rgba(124,58,237,0.07),transparent_34%)]">
          {activeLesson && activeLocation ? (
            <div className="mx-auto max-w-5xl px-4 py-6 sm:px-7 lg:px-10 lg:py-9">
              <div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-1.5 text-[10px] font-semibold uppercase tracking-[0.12em] text-white/55">
                      <ActiveLessonIcon className="h-3.5 w-3.5" style={{ color: accent }} />
                      {lessonLabel(activeLesson.type)}
                    </span>
                    {activeLesson.duration ? (
                      <span className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-1.5 text-[10px] font-medium text-white/45">
                        <Clock3 className="h-3 w-3" /> {activeLesson.duration}
                      </span>
                    ) : null}
                    {!isOwner && progress.includes(activeLesson.id) ? (
                      <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2.5 py-1.5 text-[10px] font-semibold text-emerald-300">
                        <CheckCircle2 className="h-3 w-3" /> Completed
                      </span>
                    ) : null}
                  </div>
                  <p className="mt-4 text-[11px] font-medium uppercase tracking-[0.16em] text-white/30">{activeLocation.moduleTitle}</p>
                  <h1 className="mt-2 max-w-3xl text-2xl font-semibold leading-tight tracking-[-0.025em] text-white sm:text-3xl lg:text-[2.15rem]">
                    {activeLesson.title}
                  </h1>
                </div>
                <div className="flex shrink-0 flex-wrap items-center gap-2 self-start">
                  {mediaUrl && activeLesson.type !== 'link' ? (
                    <a
                      href={mediaUrl}
                      target="_blank"
                      rel="noreferrer"
                      download
                      className="flex items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-4 py-2.5 text-xs font-semibold text-white/65 transition hover:bg-white/[0.09] hover:text-white"
                    >
                      <Download className="h-3.5 w-3.5" /> Download
                    </a>
                  ) : null}
                  {isOwner ? (
                    <button
                      type="button"
                      onClick={() => setEditorOpen(true)}
                      className="flex items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-4 py-2.5 text-xs font-semibold text-white/75 transition hover:bg-white/[0.09] hover:text-white"
                    >
                      <Pencil className="h-3.5 w-3.5" /> Edit this lesson
                    </button>
                  ) : null}
                </div>
              </div>

              <div className="mt-7 space-y-5">
                {activeLesson.type === 'video' ? (
                  mediaUrl ? (
                    <div className="overflow-hidden rounded-3xl border border-white/[0.08] bg-black shadow-2xl shadow-black/40">
                      <VideoPlayer src={mediaUrl} />
                    </div>
                  ) : (
                    <div className="flex aspect-video flex-col items-center justify-center rounded-3xl border border-dashed border-white/10 bg-white/[0.025] px-6 text-center">
                      <span className="flex h-14 w-14 items-center justify-center rounded-full border border-white/10 bg-white/[0.05] text-white/55"><Play className="ml-0.5 h-5 w-5" /></span>
                      <h2 className="mt-4 text-sm font-semibold">Video not added yet</h2>
                      <p className="mt-1 text-xs text-white/35">{isOwner ? 'Open the course builder to upload the lesson video.' : 'The creator is still preparing this lesson.'}</p>
                      {isOwner ? <button type="button" onClick={() => setEditorOpen(true)} className="mt-4 rounded-full bg-white px-4 py-2 text-xs font-semibold text-black">Add video</button> : null}
                    </div>
                  )
                ) : null}

                {activeLesson.type === 'pdf' ? (
                  mediaUrl ? (
                    <div className="overflow-hidden rounded-3xl border border-white/[0.08] bg-[#101010]">
                      <PdfViewer url={mediaUrl} />
                    </div>
                  ) : (
                    <div className="rounded-3xl border border-dashed border-white/10 bg-white/[0.025] p-10 text-center text-sm text-white/40">Document not added yet.</div>
                  )
                ) : null}

                {activeLesson.type === 'audio' ? (
                  mediaUrl ? (
                    <div className="rounded-3xl border border-white/[0.08] bg-white/[0.035] p-5">
                      <audio controls src={mediaUrl} className="w-full" />
                    </div>
                  ) : (
                    <div className="rounded-3xl border border-dashed border-white/10 bg-white/[0.025] p-10 text-center text-sm text-white/40">Audio not added yet.</div>
                  )
                ) : null}

                {activeLesson.type === 'link' ? (
                  activeLesson.content ? (
                    <a
                      href={activeLesson.content}
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center justify-between gap-4 rounded-3xl border border-white/[0.08] bg-white/[0.035] p-5 transition hover:bg-white/[0.06]"
                    >
                      <span className="min-w-0">
                        <span className="block text-sm font-semibold">Open lesson resource</span>
                        <span className="mt-1 block truncate text-xs text-white/35">{activeLesson.content}</span>
                      </span>
                      <ExternalLink className="h-5 w-5 shrink-0" style={{ color: accent }} />
                    </a>
                  ) : (
                    <div className="rounded-3xl border border-dashed border-white/10 bg-white/[0.025] p-10 text-center text-sm text-white/40">Link not added yet.</div>
                  )
                ) : null}

                {activeLesson.type === 'quiz' && quiz.length ? (
                  <div className="space-y-4">
                    {quiz.map((question, questionIndex) => (
                      <section key={`${activeLesson.id}-question-${questionIndex}`} className="rounded-3xl border border-white/[0.08] bg-white/[0.035] p-5 sm:p-6">
                        <p className="text-xs font-medium text-white/35">Question {questionIndex + 1}</p>
                        <h2 className="mt-2 text-base font-semibold">{question.question}</h2>
                        <div className="mt-4 grid gap-2">
                          {question.options.map((option, optionIndex) => {
                            const selected = quizAnswers[questionIndex] === optionIndex;
                            const answered = quizAnswers[questionIndex] !== undefined;
                            const correct = optionIndex === question.correctAnswer;
                            return (
                              <button
                                key={`${questionIndex}-${optionIndex}`}
                                type="button"
                                onClick={() => setQuizAnswers((current) => ({ ...current, [questionIndex]: optionIndex }))}
                                className={`rounded-2xl border px-4 py-3 text-left text-sm transition ${
                                  selected
                                    ? correct ? 'border-emerald-400/30 bg-emerald-400/10 text-emerald-200' : 'border-rose-400/30 bg-rose-400/10 text-rose-200'
                                    : answered && correct ? 'border-emerald-400/20 bg-emerald-400/[0.06]' : 'border-white/[0.07] bg-white/[0.025] text-white/65 hover:bg-white/[0.055]'
                                }`}
                              >
                                {option}
                              </button>
                            );
                          })}
                        </div>
                      </section>
                    ))}
                  </div>
                ) : null}

                {activeLesson.content && activeLesson.type !== 'link' && activeLesson.type !== 'pdf' && activeLesson.type !== 'audio' ? (
                  <section className="rounded-3xl border border-white/[0.08] bg-white/[0.032] p-5 sm:p-7">
                    <p className="whitespace-pre-wrap text-sm leading-7 text-white/68">{activeLesson.content}</p>
                  </section>
                ) : null}

                {activeLesson.resources?.length ? (
                  <section className="rounded-3xl border border-white/[0.08] bg-white/[0.025] p-5">
                    <h2 className="text-sm font-semibold">Lesson resources</h2>
                    <div className="mt-3 flex flex-wrap gap-2">
                      {activeLesson.resources.map((resource) => (
                        <a key={`${resource.name}-${resource.url}`} href={resource.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.045] px-3 py-2 text-xs font-medium text-white/65 hover:text-white">
                          <Download className="h-3.5 w-3.5" /> {resource.name}
                        </a>
                      ))}
                    </div>
                  </section>
                ) : null}
              </div>

              <div className="mt-7 flex flex-col gap-3 border-t border-white/[0.07] pt-5 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => previousLesson && selectLesson(previousLesson.id)}
                    disabled={!previousLesson}
                    className="flex h-10 items-center gap-2 rounded-full border border-white/10 bg-white/[0.035] px-4 text-xs font-semibold text-white/60 transition hover:bg-white/[0.07] hover:text-white disabled:cursor-not-allowed disabled:opacity-30"
                  >
                    <ChevronLeft className="h-4 w-4" /> Previous
                  </button>
                  <button
                    type="button"
                    onClick={() => nextLesson && selectLesson(nextLesson.id)}
                    disabled={!nextLesson}
                    className="flex h-10 items-center gap-2 rounded-full border border-white/10 bg-white/[0.035] px-4 text-xs font-semibold text-white/60 transition hover:bg-white/[0.07] hover:text-white disabled:cursor-not-allowed disabled:opacity-30"
                  >
                    Next <ChevronRight className="h-4 w-4" />
                  </button>
                </div>
                {!isOwner ? (
                  <button
                    type="button"
                    onClick={() => void toggleLessonCompletion()}
                    className={`flex h-10 items-center justify-center gap-2 rounded-full px-5 text-xs font-semibold transition ${
                      progress.includes(activeLesson.id)
                        ? 'border border-emerald-400/20 bg-emerald-400/10 text-emerald-300'
                        : 'text-white hover:brightness-110'
                    }`}
                    style={progress.includes(activeLesson.id) ? undefined : { backgroundColor: accent }}
                  >
                    <CheckCircle2 className="h-4 w-4" />
                    {progress.includes(activeLesson.id) ? 'Completed' : 'Mark complete'}
                  </button>
                ) : null}
              </div>

              {commentsEnabled ? (
                <section className="mt-6 border-t border-white/[0.07] pt-6">
                  <button
                    type="button"
                    onClick={() => setDiscussionOpen((open) => !open)}
                    aria-expanded={discussionOpen}
                    className="flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.035] px-4 py-2.5 text-xs font-semibold text-white/65 transition hover:bg-white/[0.07] hover:text-white"
                  >
                    <MessageCircle className="h-4 w-4" />
                    Discussion
                    <span className="rounded-full bg-white/[0.07] px-2 py-0.5 text-[10px] text-white/45">{comments.length}</span>
                    <ChevronRight className={`h-3.5 w-3.5 transition ${discussionOpen ? 'rotate-90' : ''}`} />
                  </button>

                  {discussionOpen ? (
                    <div className="mt-4 space-y-4 rounded-3xl border border-white/[0.08] bg-white/[0.025] p-4 sm:p-5">
                      <form onSubmit={handlePostComment} className="flex gap-3 rounded-2xl border border-white/[0.08] bg-black/20 p-3">
                        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white/[0.07] text-[11px] font-semibold text-white/60">
                          {initials(user?.user_metadata?.full_name || user?.email || 'Wersee')}
                        </div>
                        <div className="min-w-0 flex-1">
                          <textarea
                            value={newComment}
                            onChange={(event) => setNewComment(event.target.value)}
                            placeholder="Ask a question or share a thought…"
                            className="min-h-16 w-full resize-none bg-transparent text-sm text-white outline-none placeholder:text-white/25"
                          />
                          <div className="flex justify-end border-t border-white/[0.07] pt-2">
                            <button
                              type="submit"
                              disabled={!newComment.trim() || postingComment}
                              className="flex items-center gap-2 rounded-full bg-white px-4 py-2 text-xs font-semibold text-black disabled:cursor-not-allowed disabled:opacity-40"
                            >
                              {postingComment ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}
                              Post
                            </button>
                          </div>
                        </div>
                      </form>

                      {commentsLoading ? (
                        <div className="flex items-center justify-center gap-2 py-8 text-xs text-white/35"><Loader2 className="h-4 w-4 animate-spin" /> Loading discussion</div>
                      ) : commentsError ? (
                        <p className="py-7 text-center text-xs text-amber-200/60">{commentsError}</p>
                      ) : comments.length ? (
                        <div className="space-y-3">
                          {comments.map((comment) => {
                            const author = comment.user_name || 'Wersee member';
                            return (
                              <article key={comment.id} className="flex gap-3 rounded-2xl border border-white/[0.06] bg-white/[0.02] p-4">
                                {comment.user_avatar ? (
                                  <img src={comment.user_avatar} alt="" className="h-9 w-9 shrink-0 rounded-full object-cover" />
                                ) : (
                                  <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white/[0.07] text-[11px] font-semibold text-white/60">{initials(author)}</div>
                                )}
                                <div className="min-w-0 flex-1">
                                  <div className="flex flex-wrap items-center justify-between gap-2">
                                    <h3 className="text-xs font-semibold">{author}</h3>
                                    <time className="text-[10px] text-white/25">{new Date(comment.created_at).toLocaleDateString()}</time>
                                  </div>
                                  <p className="mt-1.5 whitespace-pre-wrap text-sm leading-6 text-white/55">{comment.content}</p>
                                </div>
                              </article>
                            );
                          })}
                        </div>
                      ) : (
                        <p className="py-7 text-center text-xs text-white/30">No discussion yet. Start the conversation.</p>
                      )}
                    </div>
                  ) : null}
                </section>
              ) : null}

              {gamificationEnabled && !isOwner ? (
                <div className="mt-6 flex items-center gap-2 text-xs text-white/35">
                  <Trophy className="h-4 w-4 text-amber-300/70" /> {points} XP earned in this course
                </div>
              ) : null}
            </div>
          ) : (
            <div className="flex min-h-full items-center justify-center px-6 py-16 text-center">
              <div className="max-w-md">
                <div
                  className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl border"
                  style={{ backgroundColor: withAlpha(accent, '16'), borderColor: withAlpha(accent, '32'), color: accent }}
                >
                  <BookOpen className="h-7 w-7" />
                </div>
                <p className="mt-5 text-[10px] font-semibold uppercase tracking-[0.18em] text-white/30">{isOwner ? 'Owner preview' : 'Course library'}</p>
                <h1 className="mt-2 text-2xl font-semibold tracking-tight">{isOwner ? 'Start building your course' : 'Lessons are coming soon'}</h1>
                <p className="mt-2 text-sm leading-6 text-white/42">
                  {isOwner
                    ? 'Create your first module, add lessons and upload content. Every saved change appears here immediately.'
                    : 'The creator has not published course content yet. Check back later.'}
                </p>
                <div className="mt-6 flex flex-wrap justify-center gap-2">
                  {isOwner ? (
                    <button type="button" onClick={() => setEditorOpen(true)} className="flex items-center gap-2 rounded-full px-5 py-2.5 text-sm font-semibold text-white" style={{ backgroundColor: accent }}>
                      <Pencil className="h-4 w-4" /> Build curriculum
                    </button>
                  ) : null}
                  <button type="button" onClick={() => setSidebarOpen(true)} className="flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-5 py-2.5 text-sm font-semibold text-white/70 lg:hidden">
                    <Layers3 className="h-4 w-4" /> Open lessons
                  </button>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {editorOpen && isOwner ? (
        <Suspense fallback={(
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#070707] text-white">
            <div className="flex items-center gap-3 rounded-full border border-white/10 bg-white/[0.04] px-4 py-2.5 text-sm text-white/70">
              <Loader2 className="h-4 w-4 animate-spin" /> Opening course builder
            </div>
          </div>
        )}>
          <LazyCourseBuilder
            key={`${listingId}-${activeLessonId || 'new'}`}
            initialData={courseData}
            initialLessonId={activeLessonId || undefined}
            listingId={listingId}
            onSave={handleSaveCourse}
            onCancel={() => setEditorOpen(false)}
          />
        </Suspense>
      ) : null}
    </div>
  );
};
